import sys

class Book:
    def __init__(self, title, author, book_id):
        self.title = title
        self.author = author
        self.book_id = book_id
        self.borrowed = False

class Library:
    def __init__(self):
        self.books = {}

    def add_book(self, title, author, book_id):
        self.books[book_id] = Book(title, author, book_id)
        print("Book added successfully.")

    def borrow_book(self, book_id):
        if book_id not in self.books:
            print("Book not found.")
            return
        if self.books[book_id].borrowed:
            print("Book already borrowed.")
            return
        self.books[book_id].borrowed = True
        print("Book borrowed successfully.")

    def return_book(self, book_id):
        if book_id not in self.books:
            print("Book not found.")
            return
        if not self.books[book_id].borrowed:
            print("Book is not borrowed.")
            return
        self.books[book_id].borrowed = False
        print("Book returned successfully.")

def parse_line(line):
    parts = line.split()
    command = parts[0].lower() if parts else ''

    if command == 'add':
        title = parts[1] if len(parts) > 1 else ''
        author = parts[2] if len(parts) > 2 else ''
        book_id = parts[3] if len(parts) > 3 else ''
        return ('add', title, author, book_id)
    elif command in ('borrow', 'return'):
        book_id = parts[1] if len(parts) > 1 else ''
        return (command, book_id)
    return (None, None, None, None)

def main():
    library = Library()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        result = parse_line(line)
        if result[0] == 'add':
            _, title, author, book_id = result
            library.add_book(title, author, book_id)
        elif result[0] == 'borrow':
            _, book_id = result
            library.borrow_book(book_id)
        elif result[0] == 'return':
            _, book_id = result
            library.return_book(book_id)

if __name__ == "__main__":
    main()
